internal static class FloatingTextVerification {
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static void V(List<byte> b,uint value){while(value>=128){b.Add((byte)(value|128));value>>=7;}b.Add((byte)value);}
 static byte[] Profile(uint actor=12){var b=new byte[128];b[0]=0x33;b[1]=0x36;b[2]=(byte)actor;b[3]=6;Buffer.BlockCopy(Encoding.UTF8.GetBytes("Tester"),0,b,4,6);Buffer.BlockCopy(BitConverter.GetBytes(10),0,b,12,4);b[16]=1;return b;}
 static byte[] Direct(uint source,uint target,uint amount,uint skill=15210000,uint type=2){var b=new List<byte>(new byte[]{4,0x38});V(b,target);V(b,6);V(b,0);V(b,source);b.AddRange(BitConverter.GetBytes(skill));b.Add(1);V(b,type);b.AddRange(new byte[]{128,0,1,85,102,119,136,1,0,0,0});V(b,10817);V(b,amount);b.AddRange(new byte[]{1,0});return b.ToArray();}
 static byte[] Tick(uint source,uint target,uint amount,uint skill,uint effect){var b=new List<byte>(new byte[]{5,0x38});V(b,target);b.Add(10);V(b,source);V(b,1);b.AddRange(BitConverter.GetBytes(effect));V(b,amount);b.AddRange(BitConverter.GetBytes(skill));return b.ToArray();}
 static void Feed(FloatingTextSignal s,byte[] b,double t,string flow="test"){s.Consume(b,0,b.Length,t,flow);}
 static void Signals(){var options=new FloatingTextOptions{Enabled=true};var s=new FloatingTextSignal();s.Configure(options,false);double t=DpsHistory.UtcNow();var hit=Direct(12,99,12480,type:3);DpsSignal.Hit parsed;Check(DpsSignal.Direct(hit,0,hit.Length,out parsed)&&parsed.Amount==12480&&parsed.CriticalKnown&&parsed.Critical,"Exact direct fixture and critical flag");Feed(s,hit,t);Check(s.Drain(t).Length==0,"Missing own identity must not publish impacts");Feed(s,Profile(),t);
  Feed(s,hit,t+.01);Feed(s,Direct(99,12,2180),t+.02);Feed(s,Direct(55,12,4360,18120000,3),t+.03);Feed(s,Direct(55,77,999),t+.04);Feed(s,Direct(12,77,800,18120000),t+.05);var events=s.Drain(t+.1);Check(events.Length==3&&events[0].Kind==0&&events[0].Critical&&events[1].Kind==1&&!events[1].Critical&&events[2].Kind==2&&events[2].Critical,"Independent own damage, incoming damage and received critical heal; ignore bystanders and outgoing heals");
  Feed(s,Tick(12,99,320,15390002,1539000011),t+.2);Feed(s,Tick(99,12,310,15390002,1539000011),t+.21);Feed(s,Tick(55,12,480,17090000,1709000011),t+.22);events=s.Drain(t+.3);Check(events.Length==3&&events[0].Kind==0&&events[1].Kind==1&&events[2].Kind==2&&!events[2].Critical,"Confirmed periodic damage and heal families without fabricated criticals");
  Feed(s,Direct(12,99,800,type:7),t+.31);Check(s.Drain(t+.4).Length==0,"Unknown direct type is not guessed to be damage");
  options.DamageTaken.Enabled=false;s.Configure(options,false);Feed(s,Direct(99,12,25),t+.5);Feed(s,hit,t+.51);events=s.Drain(t+.6);Check(events.Length==1&&events[0].Kind==0,"Disabling incoming channel preserves outgoing channel");
  Feed(s,hit,t+.7);var map=new byte[48];map[0]=0x21;map[1]=0x36;Buffer.BlockCopy(BitConverter.GetBytes(1010),0,map,6,4);Feed(s,map,t+.71);Buffer.BlockCopy(BitConverter.GetBytes(20),0,map,6,4);Feed(s,map,t+.72);Check(s.Drain(t+.8).Length==0,"Map boundary clears queued numbers");Feed(s,hit,t+.81);Check(s.Drain(t+.9).Length==0,"Await own identity after map transition");Feed(s,Profile(),t+1);
  for(int i=0;i<300;i++)Feed(s,hit,t+1.01+i*.001);Check(s.Drain(t+1.5).Length==128,"Incoming queue is bounded");Feed(s,hit,t+1.6);Check(s.Drain(t+4).Length==0,"Late captured events are not replayed as fresh hits");Feed(s,Profile(13),t+4.1);Feed(s,hit,t+4.2);Check(s.Drain(t+4.3).Length==0,"Previous character cannot generate outgoing numbers");Feed(s,Profile(13),t+4.4,"other");Feed(s,Direct(13,99,50),t+4.5);Check(s.Drain(t+4.6).Length==0,"Old connection cannot publish into active identity");
  s.Reset();Check(s.Drain(t+5).Length==0,"Transport reset clears queue");options.Enabled=false;s.Configure(options,false);Feed(s,Profile(),t+6);Feed(s,hit,t+6.1);Check(s.Drain(t+6.2).Length==0,"Disabled feature ignores gameplay");options.Enabled=true;s.Configure(options,true);Feed(s,Profile(),t+7);Feed(s,hit,t+7.1);Check(s.Drain(t+7.2).Length==0,"Preview mode cannot acquire gameplay data");
  s.Configure(options,false);var random=new Random(991);for(int i=0;i<3000;i++){var b=new byte[random.Next(0,150)];random.NextBytes(b);s.Consume(b,0,b.Length,t+8+i*.001,"fuzz");}Check(s.Drain(t+12).Length==0,"Malformed envelopes cannot synthesize text");
 }
 static void Bursts(){foreach(bool up in new[]{true,false}){var occupied=new List<RectangleF>();for(int i=0;i<16;i++){int column=i%3;float x=column==0?320:column==1?100:540;var desired=new RectangleF(x,450,160+(i%3)*8,36+(i%2)*6);var placed=FloatingTextMotion.Separate(desired,occupied,up,12);foreach(var previous in occupied){var gap=previous;gap.Inflate(5,5);Check(!gap.IntersectsWith(placed),"Burst numbers retain readable separation in both directions");}Check(placed.Top>0&&placed.Bottom<950,"Default sixteen-number burst fits the configured trail");occupied.Add(placed);}}var reader=new FloatingTextSignal();var options=new FloatingTextOptions{Enabled=true};double now=1000;reader.ReceiptClock=delegate{return now;};reader.Configure(options,false);Feed(reader,Profile(),now+1.5);Feed(reader,Direct(12,99,100,type:3),now+1.5);var events=reader.Drain(now);Check(events.Length==1&&events[0].Critical&&events[0].Time==now,"Floating text also uses reception clock when Npcap drifts ahead");}
 static void LateEnable(){double now=DpsHistory.UtcNow();var s=new FloatingTextSignal();var o=new FloatingTextOptions();s.Configure(o,false);Feed(s,Profile(),now);Feed(s,Direct(12,99,100),now+.01);Check(s.Drain(now+.02).Length==0,"Disabled channel observes identity but emits no combat");o.Enabled=true;s.Configure(o,false);Feed(s,Direct(12,99,100),now+.03);Check(s.Drain(now+.04).Length==1,"Enabling after login retains received identity");o.Enabled=false;s.Configure(o,false);o.Enabled=true;s.Configure(o,false);Feed(s,Direct(12,99,101),now+.05);Check(s.Drain(now+.06).Length==1,"Toggling on and off cannot lose character identity");s.Reset();var shared=new SkillSlotsSignal.View{Self=12,Map=1010,Flow="live"};s.Adopt(shared,"different",now+.07);Feed(s,Direct(12,99,102),now+.08,"different");Check(s.Drain(now+.09).Length==0,"Shared identity cannot cross flows");s.Adopt(shared,"live",now+.1);Feed(s,Direct(12,99,103),now+.11,"live");Check(s.Drain(now+.12).Length==1,"Same-flow confirmed bar restores missing float identity");s.Reset();Feed(s,Direct(12,99,104),now+.13,"live");Check(s.Drain(now+.14).Length==0,"Shared identity is not retained across reset");}
 static void NativePixels(string root){var style=FloatingTextStyle.Defaults(0);style.FontSize=26;using(var original=FloatingTextMotion.Glyph("12 480!!",style))using(var native=new FloatingNativeGlyph((Bitmap)original.Clone()))using(var surface=new FloatingTextSurface(260,90)){
   foreach(float phase in new[]{0f,.25f,.5f,.75f}){surface.Clear(new Rectangle(0,0,260,90));native.Draw(surface,10,10+phase,1);surface.FlushNative();using(var expected=new Bitmap(260,90,PixelFormat.Format32bppPArgb)){using(var g=Graphics.FromImage(expected)){g.InterpolationMode=InterpolationMode.HighQualityBilinear;g.PixelOffsetMode=PixelOffsetMode.Half;g.DrawImage(original,new RectangleF(10,10+phase,original.Width,original.Height),new RectangleF(0,0,original.Width,original.Height),GraphicsUnit.Pixel);}int colored=0,differences=0;for(int y=0;y<90;y++)for(int x=0;x<260;x++){var a=surface.Pixels.GetPixel(x,y);var b=expected.GetPixel(x,y);if(a.A>0)colored++;if(Math.Abs(a.A-b.A)>3||Math.Abs(a.R*a.A/255-b.R*b.A/255)>4||Math.Abs(a.G*a.A/255-b.G*b.A/255)>4||Math.Abs(a.B*a.A/255-b.B*b.A/255)>4)differences++;}Check(colored>100&&differences<20,"Native alpha retains text, outline, transparency and subpixel phase: "+phase+" differing="+differences);}}
   surface.Clear(new Rectangle(0,0,260,90));native.Draw(surface,10,10,.5);surface.FlushNative();int maximum=0;for(int y=0;y<90;y++)for(int x=0;x<260;x++)maximum=Math.Max(maximum,surface.Pixels.GetPixel(x,y).A);Check(maximum>=125&&maximum<=129,"Whole text and outline fade with correct native alpha");surface.Pixels.Save(Path.Combine(root,"designs","floating-native-alpha.png"));surface.Clear(new Rectangle(0,0,260,90));surface.FlushNative();for(int y=0;y<90;y++)for(int x=0;x<260;x++)Check(surface.Pixels.GetPixel(x,y).A==0,"Dirty-rectangle clear leaves no opaque background or ghost text");
  }}
 static void Native(EnergyOverlay owner,string root){
  uint before=OverlayNative.GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);var json=new JavaScriptSerializer();var evidence=new List<object>();
  foreach(bool up in new[]{true,false})foreach(int spread in new[]{0,50,100,160})using(var window=new FloatingTextWindow(owner,0,true)){
   var style=FloatingTextStyle.Defaults(0);style.FontSize=20;style.Spacing=0;style.Spread=spread;style.Up=up;style.Duration=1.2;window.Configure(style,true);window.Add(12480,true,0);window.Render(.1,true,false);var first=window.Positions(.1)[0];window.Add(100000000,true,.15);window.Render(.2,true,false);var later=window.Positions(.2)[0];Check(Math.Abs(first.X-later.X)<.001&&Math.Abs(later.Y-first.Y-(up?-1:1)*style.Travel*.1/style.Duration)<.002,"New wide glyphs cannot repack or teleport earlier numbers");
   for(int i=0;i<80;i++){double at=.21+i*.008;window.Add((uint)(3000+i*1337),i%3==0,at);window.Render(at+.001,true,false);var positions=window.Positions(at+.001);Check(positions.Length<=16,"Burst has a bounded visible count");for(int x=0;x<positions.Length;x++)for(int y=x+1;y<positions.Length;y++)Check(!positions[x].IntersectsWith(positions[y]),"Frozen paths overlap up="+up+" spread="+spread+" step="+i+" left="+positions[x]+" right="+positions[y]);}
   var beforePaint=json.Deserialize<Dictionary<string,object>>(json.Serialize(window.Status));for(int i=0;i<300;i++)window.Render(.9+i*.0001,true,false);var afterPaint=json.Deserialize<Dictionary<string,object>>(json.Serialize(window.Status));Check(Convert.ToInt32(afterPaint["surfaceAllocations"])==1,"A fixed size uses one native DIB, not a new HBITMAP per frame");Check(beforePaint["glyphRasterizations"].Equals(afterPaint["glyphRasterizations"]),"Moving/fading does not rasterize fonts again");Check(Convert.ToInt32(afterPaint["visualDrops"])==Convert.ToInt32(afterPaint["capacityEvictions"])+Convert.ToInt32(afterPaint["placementEvictions"]),"Every early removal has one specific visual cause");Check(Convert.ToInt64(afterPaint["diagnosticRenderCalls"])==0,"Detailed render timing remains off when diagnostics are off");
   window.Clear();var idle=json.Serialize(window.Status);for(int i=0;i<1000;i++)window.Render(5,false,false);Check(idle==json.Serialize(window.Status),"Idle windows draw and present nothing");evidence.Add(new{up,spread,state=window.Status});
  }
  uint after=OverlayNative.GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);Check(after<=before+8,"Native DIB/DC/glyph resources release after repeated windows");
  var backlog=System.Diagnostics.Stopwatch.StartNew();System.Windows.Forms.Application.DoEvents();double backlogMs=backlog.Elapsed.TotalMilliseconds;var times=new List<double>();var clock=System.Diagnostics.Stopwatch.StartNew();using(var control=new System.Windows.Forms.Control()){var handle=control.Handle;using(var pump=new FloatingFramePump(control,delegate{times.Add(clock.Elapsed.TotalMilliseconds);})){pump.Start();while(clock.Elapsed.TotalMilliseconds<650){System.Windows.Forms.Application.DoEvents();System.Threading.Thread.Sleep(1);}pump.Stop();int count=times.Count;double end=clock.Elapsed.TotalMilliseconds+40;while(clock.Elapsed.TotalMilliseconds<end){System.Windows.Forms.Application.DoEvents();System.Threading.Thread.Sleep(1);}Check(times.Count==count,"Stopped frame pump cannot deliver a queued late animation");Check(times.Count>10,"Active frame pump delivered "+times.Count+" frames in "+clock.Elapsed.TotalMilliseconds+" ms");}}
  var gaps=new List<double>();for(int i=1;i<times.Count;i++)gaps.Add(times[i]-times[i-1]);gaps.Sort();File.WriteAllText(Path.Combine(root,"floating-native-verification.json"),json.Serialize(new{gdiBefore=before,gdiAfter=after,frames=times.Count,stressMessageDrainMs=backlogMs,medianIntervalMs=gaps[gaps.Count/2],p95IntervalMs=gaps[(int)(gaps.Count*.95)],scope="Isolated UI message pump, no gameplay/FPS/GPU claim",cases=evidence}));
 }
 static void Settings(){var json=new JavaScriptSerializer();var o=FloatingTextOptions.Read(new Dictionary<string,object>());Check(!o.Enabled&&o.DamageDealt.Up&&!o.DamageTaken.Up,"Legacy settings keep new overlay off and independent defaults");o.Enabled=true;o.DamageDealt.Color="#123456";o.DamageTaken.OutlineColor="#654321";o.HealingReceived.Duration=2.8;o.HealingReceived.Scale=160;o.DamageDealt.Spread=0;o.DamageTaken.Spacing=0;var copy=o.Copy();copy.DamageDealt.Color="#FFFFFF";Check(o.DamageDealt.Color=="#123456","Category snapshots must not alias");var restored=FloatingTextOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{floatingText=o})));Check(FloatingTextOptions.Same(o,restored),"All independent styles survive serialization");o.DamageDealt.Duration=double.NaN;o.HealingReceived.Travel=int.MaxValue;o.DamageTaken.OutlineWidth=-20;o.Normalize();Check(o.DamageDealt.Duration==1.35&&o.HealingReceived.Travel==400&&o.DamageTaken.OutlineWidth==0,"Invalid options remain bounded");
  var a=new EnergyConfiguration{Options=new EnergyBarOptions()};var h=new ConfigurationHistory();h.Observe(a);var b=a.Copy();b.FloatingText.Enabled=true;b.FloatingText.DamageTaken.X=35;h.Observe(b);EnergyConfiguration undo;Check(h.Undo(out undo)&&ConfigurationHistory.Same(a,undo)&&h.Redo(out undo)&&ConfigurationHistory.Same(b,undo),"Floating styles participate in shared undo/redo");
  Check(FloatingTextMotion.Number(12480,0,true)=="12 480!!"&&FloatingTextMotion.Number(2180,1,false)=="−2 180"&&FloatingTextMotion.Number(4360,2,true)=="+4 360!!","Critical exclamations and unambiguous category numbers");var style=FloatingTextStyle.Defaults(0);Check(FloatingTextMotion.Alpha(0,1)==0&&FloatingTextMotion.Alpha(1,1)==0&&FloatingTextMotion.Alpha(.5,1)==1,"Fade in and out without discontinuity");Check(FloatingTextMotion.Offset(.7,style)<0,"Upward movement");style.Up=false;Check(FloatingTextMotion.Offset(.7,style)>0,"Downward movement");
 }
 static void Label(Graphics g,string text,float x,float y,float size,Color color,bool bold=false){using(var f=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))using(var b=new SolidBrush(color))g.DrawString(text,f,b,x,y);}
 static void References(string folder){Directory.CreateDirectory(folder);using(var image=new Bitmap(1440,760,PixelFormat.Format32bppPArgb))using(var g=Graphics.FromImage(image))using(var background=new LinearGradientBrush(new Rectangle(0,0,1440,760),Color.FromArgb(24,29,37),Color.FromArgb(11,15,22),30f)){
   g.FillRectangle(background,0,0,1440,760);Label(g,"FLOATING COMBAT TEXT",44,32,15,Color.FromArgb(104,204,181),true);Label(g,"Tres canales. Tu forma de ver el combate.",44,66,33,Color.FromArgb(238,241,246),true);Label(g,"Texto sin recuadro · Bahnschrift · color y borde independientes · críticos con !!",45,118,17,Color.FromArgb(150,160,177));
   for(int k=0;k<3;k++){int x=44+k*455;using(var b=new SolidBrush(Color.FromArgb(31,38,48)))g.FillRectangle(b,x,180,430,490);using(var p=new Pen(Color.FromArgb(50,129,151,161)))g.DrawRectangle(p,x,180,430,490);var o=FloatingTextStyle.Defaults(k);o.FontSize=42;Label(g,UiLanguage.Text(FloatingTextOptions.Name(k),"es"),x+22,202,21,ColorTranslator.FromHtml(o.Color),true);Label(g,k==1?"↓ Hacia abajo":"↑ Hacia arriba",x+22,238,15,Color.FromArgb(157,169,183));
    using(var attributes=new ImageAttributes()){var matrix=new ColorMatrix();for(int n=0;n<3;n++){double age=n==0?.17:n==1?.62:1.07;float y=k==1?320+n*90:555-n*90;uint amount=k==0?(n==0?12480u:n==1?3620u:980u):k==1?(n==0?2180u:n==1?840u:310u):(n==0?4360u:n==1?1650u:480u);using(var glyph=FloatingTextMotion.Glyph(FloatingTextMotion.Number(amount,k,n==0),o))FloatingTextMotion.Sprite(g,glyph,x+215-glyph.Width/2f,y,FloatingTextMotion.Alpha(age,o.Duration),attributes,matrix);}}
    Label(g,k==0?"Dorado suave":k==1?"Coral":"Verde menta",x+22,620,15,Color.FromArgb(170,182,195));}
